import React from 'react';

import {getLoadedEngine, loadEngine} from './engines/registry';
import type {VizEngine, VizEngineStatus, VizMode} from './types';

export interface VizEngineState {
    status: VizEngineStatus;
    engine: VizEngine | undefined;
    error: Error | undefined;
    retry: () => void;
}

/**
 * Подтягивает движок для режима. Пока новый движок грузится, хук продолжает
 * отдавать предыдущий — виджет держит прошлый кадр вместо скелетона.
 */
export function useVizEngine(mode: VizMode): VizEngineState {
    const [attempt, setAttempt] = React.useState(0);
    const [state, setState] = React.useState<{engine?: VizEngine; error?: Error; loadingMode?: VizMode}>(
        () => ({engine: getLoadedEngine(mode)}),
    );

    React.useEffect(() => {
        const cached = getLoadedEngine(mode);
        if (cached) {
            setState({engine: cached});
            return undefined;
        }
        let cancelled = false;
        setState((prev) => ({engine: prev.engine, loadingMode: mode}));
        loadEngine(mode).then(
            (engine) => {
                if (!cancelled) {
                    setState({engine});
                }
            },
            (error: unknown) => {
                if (!cancelled) {
                    setState((prev) => ({
                        engine: prev.engine,
                        error: error instanceof Error ? error : new Error(String(error)),
                    }));
                }
            },
        );
        return () => {
            cancelled = true;
        };
    }, [mode, attempt]);

    const retry = React.useCallback(() => setAttempt((n) => n + 1), []);

    let status: VizEngineStatus = 'idle';
    if (state.error) {
        status = 'error';
    } else if (state.engine?.mode === mode) {
        status = 'ready';
    } else if (state.loadingMode === mode) {
        status = 'loading';
    }

    return {status, engine: state.engine, error: state.error, retry};
}
EOF
cat > src/widget/DataTable.tsx <<'EOF'
import React from 'react';
import {Table, Text} from '@gravity-ui/uikit';

import type {VizDataset} from './types';

interface Row {
    t: number;
    values: (number | null)[];
}

const MAX_ROWS = 200;

/**
 * Табличное представление — значения доступны и без наведения на график.
 * Для плотных рядов показываем последние строки, чтобы не раздувать DOM.
 */
export function DataTable({dataset, timeZone}: {dataset: VizDataset; timeZone?: string}) {
    const {rows, total} = React.useMemo(() => {
        const byT = new Map<number, (number | null)[]>();
        dataset.series.forEach((s, i) => {
            for (const p of s.points) {
                let row = byT.get(p.t);
                if (!row) {
                    row = new Array<number | null>(dataset.series.length).fill(null);
                    byT.set(p.t, row);
                }
                row[i] = p.y;
            }
        });
        const all = Array.from(byT.entries())
            .sort((a, b) => a[0] - b[0])
            .map(([t, values]) => ({t, values}));
        return {rows: all.slice(-MAX_ROWS), total: all.length};
    }, [dataset]);

    const dateFmt = React.useMemo(
        () =>
            new Intl.DateTimeFormat('ru-RU', {
                dateStyle: 'short',
                timeStyle: 'medium',
                timeZone: timeZone ?? dataset.timeZone,
            }),
        [timeZone, dataset.timeZone],
    );
    const numFmt = React.useMemo(() => new Intl.NumberFormat('ru-RU', {maximumFractionDigits: 2}), []);

    const columns = [
        {id: 'time', name: 'Время', template: (row: Row) => dateFmt.format(row.t)},
        ...dataset.series.map((s, i) => ({
            id: s.id,
            name: dataset.unit ? `${s.name}, ${dataset.unit}` : s.name,
            align: 'end' as const,
            template: (row: Row) => {
                const v = row.values[i];
                return v === null || v === undefined ? '—' : numFmt.format(v);
            },
        })),
    ];

    return (
        <div style={{overflow: 'auto', height: '100%', fontVariantNumeric: 'tabular-nums'}}>
            {total > rows.length ? (
                <Text variant="caption-2" color="secondary" as="div" style={{padding: '4px 0 8px'}}>
                    Показаны последние {rows.length} из {total} строк
                </Text>
            ) : null}
            <Table data={rows} columns={columns} getRowDescriptor={(row) => ({id: String(row.t)})} />
        </div>
    );
}
EOF
