import {chromium} from 'playwright';

const url = process.argv[2] ?? 'http://localhost:4173/';
const browser = await chromium.launch();
const page = await browser.newPage({viewport: {width: 1200, height: 720}, deviceScaleFactor: 1});

const chunks = [];
const errors = [];
page.on('request', (r) => {
    const u = r.url();
    if (u.includes('/assets/') && u.endsWith('.js')) chunks.push(u.split('/assets/')[1]);
});
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`[${m.type()}] ${m.text()}`); });
page.on('pageerror', (e) => errors.push(`[pageerror] ${e.message}`));

function mark(label) {
    const idx = chunks.length;
    console.log(`\n== ${label}: chunks loaded so far (${idx}) ==`);
    console.log(chunks.filter((c) => !/^[a-z]{2}(-[a-z]+)?-[\w-]+\.js$/.test(c)).join('\n'));
}

await page.goto(url, {waitUntil: 'networkidle'});
await page.waitForSelector('.gcharts-chart, .chartkit-yagr, canvas', {timeout: 15000}).catch(() => {});
await page.waitForTimeout(800);
mark('after initial load (sales)');
await page.screenshot({path: '/tmp/shots/1-sales-light.png'});

// hover a point to show tooltip
const plot = await page.$('.viz-widget__body');
const box = await plot.boundingBox();
await page.mouse.move(box.x + box.width * 0.6, box.y + box.height * 0.45);
await page.waitForTimeout(400);
await page.screenshot({path: '/tmp/shots/1b-sales-tooltip.png'});

// switch to monitoring
