await page.mouse.move(box.x + box.width * 0.62, box.y + box.height * 0.4);
await page.waitForTimeout(400);
await page.screenshot({path: '/tmp/shots/2b-monitoring-tooltip.png'});

// dark theme
await page.getByText('Тёмная тема').click();
await page.waitForTimeout(800);
await page.mouse.move(10, 10);
await page.waitForTimeout(300);
await page.screenshot({path: '/tmp/shots/3-monitoring-dark.png'});
await page.getByText('Продажи').click();
await page.waitForTimeout(1200);
await page.screenshot({path: '/tmp/shots/4-sales-dark.png'});

// table view
await page.getByTitle('Показать таблицу').click();
await page.waitForTimeout(500);
await page.screenshot({path: '/tmp/shots/5-table-dark.png'});

console.log('\n== console errors/warnings ==');
console.log(errors.length ? errors.join('\n') : '(none)');
console.log('\n== engine label ==', await page.textContent('.viz-widget__engine'));
await browser.close();
